import { z } from "zod";

function containsUnsafeRefCharacter(value: string): boolean {
  return [...value].some((character) => {
    const code = character.charCodeAt(0);
    return code <= 31 || code === 127 || character.trim() === "";
  });
}

export const scanStatusSchema = z.enum([
  "QUEUED",
  "RUNNING",
  "COMPLETED",
  "FAILED",
]);
export type ScanStatus = z.infer<typeof scanStatusSchema>;

export const scanStageSchema = z.enum([
  "QUEUED",
  "LOADING_DESIRED",
  "READING_LIVE",
  "COMPARING",
  "SAVING_RESULT",
  "COMPLETED",
  "FAILED",
]);
export type ScanStage = z.infer<typeof scanStageSchema>;

export const comparisonOutcomeSchema = z.enum([
  "IN_SYNC",
  "DRIFTED",
  "MISSING_LIVE",
]);
export type ComparisonOutcome = z.infer<typeof comparisonOutcomeSchema>;

export const startScanSchema = z
  .object({
    ref: z
      .string()
      .trim()
      .min(1)
      .max(200)
      .refine((value) => !containsUnsafeRefCharacter(value), {
        message: "ref must not contain whitespace or control characters",
      }),
  })
  .strict();

export const historyLimitSchema = z.coerce.number().int().min(1).max(50);

export interface DeploymentTarget {
  apiVersion: "apps/v1";
  kind: "Deployment";
  name: string;
  namespace: string;
}

export interface ContainerProjection {
  image: string;
  name: string;
}

export interface DeploymentProjection {
  containers: ContainerProjection[];
  replicas: number;
}

export interface Difference {
  desired: number | string;
  field: string;
  live: number | string | null;
}

export interface ComparisonResult {
  differences: Difference[];
  outcome: ComparisonOutcome;
}

export interface SafeScanError {
  code: ScanErrorCode;
  message: string;
}

export type ScanErrorCode =
  | "CONFIGURATION_INVALID"
  | "GITHUB_FILE_NOT_FOUND"
  | "GITHUB_REF_NOT_FOUND"
  | "GITHUB_RESPONSE_INVALID"
  | "GITHUB_TIMEOUT"
  | "GITHUB_UNAVAILABLE"
  | "INTERNAL_ERROR"
  | "KUBERNETES_FORBIDDEN"
  | "KUBERNETES_TIMEOUT"
  | "KUBERNETES_UNAVAILABLE"
  | "MANIFEST_INVALID"
  | "MANIFEST_UNSUPPORTED"
  | "SCAN_ACTIVE"
  | "SCAN_NOT_FOUND"
  | "STORAGE_UNAVAILABLE"
  | "STORAGE_WRITE_FAILED";

export interface StageRecord {
  at: string;
  stage: ScanStage;
}

export interface ScanRecord {
  completedAt: string | null;
  createdAt: string;
  differences: Difference[];
  durable: boolean;
  error: SafeScanError | null;
  id: string;
  live: DeploymentProjection | null;
  outcome: ComparisonOutcome | null;
  requestedRef: string;
  resolvedSha: string | null;
  stage: ScanStage;
  stages: StageRecord[];
  status: ScanStatus;
  target: DeploymentTarget | null;
  updatedAt: string;
  desired: DeploymentProjection | null;
}

export interface SourceMetadata {
  manifestPath: string;
  repository: string;
}
import type { ScanRecord } from "@/server/scans/contracts";
import { historyLimitSchema, startScanSchema } from "@/server/scans/contracts";
import { ScanExecutionError } from "@/server/scans/errors";
import type { ScanScheduler, ScanService } from "@/server/scans/service";

const MAX_REQUEST_BYTES = 1_024;

function json(body: unknown, status = 200): Response {
  return Response.json(body, { status });
}

export function scanErrorResponse(error: unknown): Response {
  if (!(error instanceof ScanExecutionError)) {
    return json(
      { error: new ScanExecutionError("INTERNAL_ERROR").toSafeError() },
      500,
    );
  }

  const status =
    error.code === "SCAN_ACTIVE"
      ? 409
      : error.code === "SCAN_NOT_FOUND"
        ? 404
        : error.code.startsWith("STORAGE_")
          ? 503
          : error.code === "CONFIGURATION_INVALID"
            ? 503
            : 500;
  return json({ error: error.toSafeError() }, status);
}

function scanEnvelope(scan: ScanRecord): { scan: ScanRecord } {
  return { scan };
}

async function readBoundedBody(request: Request): Promise<string | null> {
  const declaredLength = request.headers.get("content-length");
  if (
    declaredLength !== null &&
    Number.isFinite(Number(declaredLength)) &&
    Number(declaredLength) > MAX_REQUEST_BYTES
  ) {
    return null;
  }
  if (request.body === null) {
    return "";
  }

  const reader = request.body.getReader();
  const decoder = new TextDecoder();
  let totalBytes = 0;
  let text = "";
  while (true) {
    const chunk = await reader.read();
    if (chunk.done) {
      return text + decoder.decode();
    }
    totalBytes += chunk.value.byteLength;
    if (totalBytes > MAX_REQUEST_BYTES) {
      await reader.cancel();
      return null;
    }
    text += decoder.decode(chunk.value, { stream: true });
  }
}

export async function startScanResponse(
  request: Request,
  service: ScanService,
  schedule: ScanScheduler,
): Promise<Response> {
  try {
    const text = await readBoundedBody(request);
    if (text === null) {
      return json(
        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
        400,
      );
    }
    const parsed = startScanSchema.safeParse(JSON.parse(text));
    if (!parsed.success) {
      return json(
        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
        400,
      );
    }

    const scan = service.startScheduled(parsed.data.ref, schedule);
    return json(scanEnvelope(scan), 202);
  } catch (error) {
    if (error instanceof SyntaxError) {
      return json(
        { error: { code: "INVALID_REQUEST", message: "Request is invalid." } },
        400,
      );
    }
    return scanErrorResponse(error);
  }
}

export function listScansResponse(
  request: Request,
  service: ScanService,
): Response {
  try {
    const rawLimit = new URL(request.url).searchParams.get("limit") ?? "20";
    const limit = historyLimitSchema.safeParse(rawLimit);
    if (!limit.success) {
      return json(
        { error: { code: "INVALID_LIMIT", message: "Limit is invalid." } },
        400,
      );
    }
    return json({ scans: service.list(limit.data) });
  } catch (error) {
    return scanErrorResponse(error);
  }
}

export function getScanResponse(id: string, service: ScanService): Response {
  try {
    const scan = service.get(id);
    if (!scan) {
      throw new ScanExecutionError("SCAN_NOT_FOUND");
    }
    return json(scanEnvelope(scan));
  } catch (error) {
    return scanErrorResponse(error);
  }
}

export function sourceResponse(service: ScanService): Response {
  return json({ source: service.source() });
}
import { after } from "next/server";

import {
  listScansResponse,
  scanErrorResponse,
  startScanResponse,
} from "@/server/scans/api";
import { getScanService } from "@/server/scans/runtime";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export function GET(request: Request): Response {
  try {
    return listScansResponse(request, getScanService());
  } catch (error) {
    return scanErrorResponse(error);
  }
}

export async function POST(request: Request): Promise<Response> {
  try {
    return await startScanResponse(request, getScanService(), after);
  } catch (error) {
    return scanErrorResponse(error);
  }
}
import { getScanResponse, scanErrorResponse } from "@/server/scans/api";
import { getScanService } from "@/server/scans/runtime";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export function GET(
  _request: Request,
  context: { params: Promise<{ id: string }> },
): Promise<Response> {
  return context.params.then(({ id }) => {
    try {
      return getScanResponse(id, getScanService());
    } catch (error) {
      return scanErrorResponse(error);
    }
  });
}
import { scanErrorResponse, sourceResponse } from "@/server/scans/api";
import { getScanService } from "@/server/scans/runtime";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export function GET(): Response {
  try {
    return sourceResponse(getScanService());
  } catch (error) {
    return scanErrorResponse(error);
  }
}

