--- 1 ---
import { parseAllDocuments } from "yaml";
import { z } from "zod";

import type {
  ComparisonResult,
  DeploymentProjection,
  DeploymentTarget,
  Difference,
} from "@/server/scans/contracts";
import { ScanExecutionError } from "@/server/scans/errors";

const dnsSubdomain = z
  .string()
  .min(1)
  .max(253)
  .regex(/^[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?$/)
  .refine((value) => value.split(".").every((label) => label.length <= 63));
const dnsLabel = z
  .string()
  .min(1)
  .max(63)
  .regex(/^[a-z0-9](?:[-a-z0-9]*[a-z0-9])?$/);
const containerSchema = z.object({
  image: z.string().min(1).max(2_048),
  name: dnsLabel,
});
const resourceIdentitySchema = z.object({
  apiVersion: z.string(),
  kind: z.string(),
});
const deploymentSchema = z.object({
  apiVersion: z.string(),
  kind: z.string(),
  metadata: z.object({
    name: dnsSubdomain,
    namespace: dnsLabel,
  }),
  spec: z.object({
    replicas: z.number().int().min(0).optional(),
    template: z.object({
      spec: z.object({
        containers: z.array(containerSchema).min(1),
      }),
    }),
  }),
});

export interface DesiredDeployment {
  projection: DeploymentProjection;
  target: DeploymentTarget;
}

export function parseDesiredDeployment(yaml: string): DesiredDeployment {
  let documents;
  try {
    documents = parseAllDocuments(yaml);
  } catch (error) {
    throw new ScanExecutionError("MANIFEST_INVALID", { cause: error });
  }

  if (
    documents.length !== 1 ||
    documents[0]?.errors.length !== 0 ||
    documents[0].contents === null
  ) {
    throw new ScanExecutionError("MANIFEST_INVALID");
  }

  const resource = documents[0].toJS();
  const identity = resourceIdentitySchema.safeParse(resource);
  if (
    identity.success &&
    (identity.data.apiVersion !== "apps/v1" ||
      identity.data.kind !== "Deployment")
  ) {
    throw new ScanExecutionError("MANIFEST_UNSUPPORTED");
  }

  const result = deploymentSchema.safeParse(resource);
  if (!result.success) {
    throw new ScanExecutionError("MANIFEST_INVALID");
  }

  const containerNames = result.data.spec.template.spec.containers.map(
    ({ name }) => name,
  );
  if (new Set(containerNames).size !== containerNames.length) {
    throw new ScanExecutionError("MANIFEST_INVALID");
  }

  return {
    projection: {
      containers: result.data.spec.template.spec.containers
        .map(({ image, name }) => ({ image, name }))
        .sort((left, right) => left.name.localeCompare(right.name)),
      replicas: result.data.spec.replicas ?? 1,
    },
    target: {
      apiVersion: "apps/v1",
      kind: "Deployment",
      name: result.data.metadata.name,
      namespace: result.data.metadata.namespace,
    },
  };
}

export function compareDeployments(
  desired: DeploymentProjection,
  live: DeploymentProjection | null,
): ComparisonResult {
  if (live === null) {
    return { differences: [], outcome: "MISSING_LIVE" };
  }

  const differences: Difference[] = [];
  if (desired.replicas !== live.replicas) {
    differences.push({
      desired: desired.replicas,
      field: "spec.replicas",
      live: live.replicas,
    });
  }

  const liveContainers = new Map(
    live.containers.map((container) => [container.name, container.image]),
  );
  for (const container of desired.containers) {
    const liveImage = liveContainers.get(container.name) ?? null;
    if (container.image !== liveImage) {
      differences.push({
        desired: container.image,
        field: `spec.template.spec.containers[name=${container.name}].image`,
        live: liveImage,
      });
    }
  }

  return {
    differences,
    outcome: differences.length === 0 ? "IN_SYNC" : "DRIFTED",
  };
}

--- 2 ---
import { randomUUID } from "node:crypto";

import type { ScanRecord, SourceMetadata } from "@/server/scans/contracts";
import {
  compareDeployments,
  parseDesiredDeployment,
} from "@/server/scans/deployment";
import { safeScanError, ScanExecutionError } from "@/server/scans/errors";
import type { DesiredStateReader } from "@/server/scans/github";
import type { LiveDeploymentReader } from "@/server/scans/kubernetes";
import { noOpScanLogger, type ScanLogger } from "@/server/scans/log";
import type { ScanRepository } from "@/server/scans/repository";

export type Clock = () => string;
export type IdFactory = () => string;
export type ScanScheduler = (task: () => Promise<void>) => void;

const MAX_VOLATILE_FAILURES = 50;

export class ScanService {
  private activeScanId: string | null = null;
  private volatileHistoryIncomplete = false;
  private readonly volatileFailures = new Map<string, ScanRecord>();

  constructor(
    private readonly repository: ScanRepository,
    private readonly desiredState: DesiredStateReader,
    private readonly liveState: LiveDeploymentReader,
    private readonly sourceMetadata: SourceMetadata,
    private readonly clock: Clock = () => new Date().toISOString(),
    private readonly idFactory: IdFactory = randomUUID,
    private readonly logger: ScanLogger = noOpScanLogger,
  ) {}

  source(): SourceMetadata {
    return this.sourceMetadata;
  }

  checkPersistence(): void {
    if (this.volatileHistoryIncomplete) {
      throw new ScanExecutionError("STORAGE_UNAVAILABLE");
    }
    this.repository.checkWritable();
  }

  start(requestedRef: string): ScanRecord {
    this.requireCompleteHistory();
    if (this.activeScanId !== null) {
      throw new ScanExecutionError("SCAN_ACTIVE");
    }

    const id = this.idFactory();
    this.activeScanId = id;
    try {
      const scan = this.repository.createQueued(id, requestedRef, this.clock());
      this.logger.stage(id, "QUEUED");
      return scan;
    } catch (error) {
      this.activeScanId = null;
      throw error;
    }
  }

  startScheduled(requestedRef: string, schedule: ScanScheduler): ScanRecord {
    const scan = this.start(requestedRef);
    try {
      schedule(() => this.run(scan.id));
      return scan;
    } catch (error) {
      this.recordSchedulingFailure(scan, error);
      throw error;
    }
  }

  async run(id: string): Promise<void> {
    if (this.activeScanId !== id) {
      return;
    }

    try {
      this.repository.transition(
        id,
        "LOADING_DESIRED",
        "RUNNING",
        this.clock(),
      );
      this.logger.stage(id, "LOADING_DESIRED");
      const queued = this.repository.get(id);
      if (!queued) {
        throw new ScanExecutionError("SCAN_NOT_FOUND");
      }

      const desiredSource = await this.desiredState.load(queued.requestedRef);
      const desired = parseDesiredDeployment(desiredSource.yaml);
      this.repository.saveDesired(
        id,
        desiredSource.resolvedSha,
        desired.target,
        desired.projection,
        this.clock(),
      );
      this.logger.stage(id, "READING_LIVE");

      const live = await this.liveState.read(desired.target);
      this.repository.saveLive(id, live, this.clock());
      this.logger.stage(id, "COMPARING");
      const result = compareDeployments(desired.projection, live);

      this.repository.transition(id, "SAVING_RESULT", "RUNNING", this.clock());
      this.logger.stage(id, "SAVING_RESULT");
      this.repository.complete(id, result, this.clock());
      this.logger.stage(id, "COMPLETED");
    } catch (error) {
      const safeError = safeScanError(error);
      try {
        this.repository.fail(id, safeError, this.clock());
        this.logger.failed(id, safeError.code, true);
      } catch {
        this.recordVolatileStorageFailure(id);
        this.logger.failed(id, "STORAGE_WRITE_FAILED", false);
      }
    } finally {
      this.activeScanId = null;
    }
  }

  get(id: string): ScanRecord | null {
    const volatile = this.volatileFailures.get(id);
    if (volatile) {
      return volatile;
    }
    this.requireCompleteHistory();
    return this.repository.get(id);
  }

  list(limit: number): ScanRecord[] {
    this.requireCompleteHistory();
    const durable = this.repository.list(limit);
    return durable.map(
      (record) => this.volatileFailures.get(record.id) ?? record,
    );
  }

  private recordSchedulingFailure(scan: ScanRecord, error: unknown): void {
    try {
      const safeError = safeScanError(error);
      try {
        this.repository.fail(scan.id, safeError, this.clock());
        this.logger.failed(scan.id, safeError.code, true);
      } catch {
        this.recordVolatileStorageFailure(scan.id, scan);
        this.logger.failed(scan.id, "STORAGE_WRITE_FAILED", false);
      }
    } finally {
      if (this.activeScanId === scan.id) {
        this.activeScanId = null;
      }
    }
  }

  private recordVolatileStorageFailure(
    id: string,
    fallback: ScanRecord | null = null,
  ): void {
    let record = fallback;
    if (!record) {
      try {
        record = this.repository.get(id);
      } catch {
        // The API will surface repository unavailability if reads also fail.
      }
    }
    if (!record) {
      return;
    }

    const at = this.clock();
    this.volatileFailures.set(id, {
      ...record,
      completedAt: at,
      durable: false,
      error: new ScanExecutionError("STORAGE_WRITE_FAILED").toSafeError(),
      stage: "FAILED",
      status: "FAILED",
      updatedAt: at,
    });
    if (this.volatileFailures.size > MAX_VOLATILE_FAILURES) {
      const oldest = this.volatileFailures.keys().next().value as
        string | undefined;
      if (oldest) {
        this.volatileFailures.delete(oldest);
        this.volatileHistoryIncomplete = true;
      }
    }
  }

  private requireCompleteHistory(): void {
    if (this.volatileHistoryIncomplete) {
      throw new ScanExecutionError("STORAGE_UNAVAILABLE");
    }
  }
}

--- 3 ---
import { afterEach, describe, expect, it, vi } from "vitest";

import {
  getScanResponse,
  listScansResponse,
  sourceResponse,
  startScanResponse,
} from "@/server/scans/api";
import { ScanExecutionError } from "@/server/scans/errors";
import { SqliteScanRepository } from "@/server/scans/repository";
import { ScanService } from "@/server/scans/service";

const repositories: SqliteScanRepository[] = [];
const SHA = "0123456789abcdef0123456789abcdef01234567";
const MANIFEST = `apiVersion: apps/v1
kind: Deployment
metadata:
  name: app
  namespace: demo
spec:
  template:
    spec:
      containers:
        - name: api
          image: api:1
`;

function createService(): ScanService {
  const repository = new SqliteScanRepository(":memory:");
  repositories.push(repository);
  let id = 0;
  return new ScanService(
    repository,
    {
      load: vi.fn().mockResolvedValue({ resolvedSha: SHA, yaml: MANIFEST }),
    },
    {
      read: vi.fn().mockResolvedValue({
        containers: [{ image: "api:1", name: "api" }],
        replicas: 1,
      }),
    },
    { manifestPath: "deployment.yaml", repository: "owner/repo" },
    () => "2026-07-31T00:00:00.000Z",
    () => `scan-${++id}`,
  );
}

function post(body: string): Request {
  return new Request("http://localhost/api/scans", {
    body,
    headers: { "content-type": "application/json" },
    method: "POST",
  });
}

afterEach(() => {
  for (const repository of repositories.splice(0)) {
    repository.close();
  }
});

describe("scan API contracts", () => {
  it("validates input before creating work", async () => {
    const service = createService();
    for (const body of ["{}", '{"ref":"bad ref"}', "not-json"]) {
      const response = await startScanResponse(post(body), service, vi.fn());
      expect(response.status).toBe(400);
      await expect(response.json()).resolves.toEqual({
        error: { code: "INVALID_REQUEST", message: "Request is invalid." },
      });
    }
  });

  it("cancels chunked input as soon as the byte limit is exceeded", async () => {
    let cancelled = false;
    const chunk = new Uint8Array(600).fill(97);
    const body = new ReadableStream<Uint8Array>({
      cancel() {
        cancelled = true;
      },
      pull(controller) {
        controller.enqueue(chunk);
      },
    });
    const request = new Request("http://localhost/api/scans", {
      body,
      duplex: "half",
      method: "POST",
    } as RequestInit & { duplex: "half" });

    const response = await startScanResponse(request, createService(), vi.fn());

    expect(response.status).toBe(400);
    expect(cancelled).toBe(true);
  });

  it("returns 202 immediately, then polling observes persisted completion", async () => {
    const service = createService();
    const tasks: Array<() => Promise<void>> = [];
    const response = await startScanResponse(
      post('{"ref":"main"}'),
      service,
      (task) => tasks.push(task),
    );

    expect(response.status).toBe(202);
    const queued = (await response.json()) as { scan: { id: string } };
    expect(queued.scan).toMatchObject({ id: "scan-1", status: "QUEUED" });
    expect(tasks).toHaveLength(1);

    await tasks[0]!();
    const detail = getScanResponse("scan-1", service);
    expect(detail.status).toBe(200);
    await expect(detail.json()).resolves.toMatchObject({
      scan: {
        outcome: "IN_SYNC",
        resolvedSha: SHA,
        status: "COMPLETED",
      },
    });
  });

  it("returns active conflict without scheduling a second workflow", async () => {
    const service = createService();
    const schedule = vi.fn();
    expect(
      (await startScanResponse(post('{"ref":"main"}'), service, schedule))
        .status,
    ).toBe(202);

    const conflict = await startScanResponse(
      post('{"ref":"other"}'),
      service,
      schedule,
    );
    expect(conflict.status).toBe(409);
    await expect(conflict.json()).resolves.toEqual({
      error: {
        code: "SCAN_ACTIVE",
        message: "Another scan is active.",
      },
    });
    expect(schedule).toHaveBeenCalledOnce();
  });

  it("terminalizes scheduler rejection and admits a subsequent start", async () => {
    const service = createService();
    const rejectedSchedule = vi.fn(() => {
      throw new Error("unsafe scheduler detail");
    });

    const rejected = await startScanResponse(
      post('{"ref":"main"}'),
      service,
      rejectedSchedule,
    );

    expect(rejected.status).toBe(500);
    await expect(rejected.json()).resolves.toEqual({
      error: {
        code: "INTERNAL_ERROR",
        message: "Scan failed unexpectedly.",
      },
    });
    expect(rejectedSchedule).toHaveBeenCalledOnce();

    const history = listScansResponse(
      new Request("http://localhost/api/scans"),
      service,
    );
    await expect(history.json()).resolves.toMatchObject({
      scans: [
        {
          durable: true,
          error: {
            code: "INTERNAL_ERROR",
            message: "Scan failed unexpectedly.",
          },
          id: "scan-1",
          stages: [{ stage: "QUEUED" }, { stage: "FAILED" }],
          status: "FAILED",
        },
      ],
    });

    const tasks: Array<() => Promise<void>> = [];
    const next = await startScanResponse(
      post('{"ref":"next"}'),
      service,
      (task) => tasks.push(task),
    );
    expect(next.status).toBe(202);
    expect(tasks).toHaveLength(1);
  });

  it("returns bounded history, source metadata, invalid limit, and not-found", async () => {
    const service = createService();
    service.start("main");

    const history = listScansResponse(
      new Request("http://localhost/api/scans?limit=1"),
      service,
    );
    expect(history.status).toBe(200);
    await expect(history.json()).resolves.toMatchObject({
      scans: [{ id: "scan-1" }],
    });

    const badLimit = listScansResponse(
      new Request("http://localhost/api/scans?limit=51"),
      service,
    );
    expect(badLimit.status).toBe(400);

    const missing = getScanResponse("missing", service);
    expect(missing.status).toBe(404);
    await expect(missing.json()).resolves.toEqual({
      error: { code: "SCAN_NOT_FOUND", message: "Scan was not found." },
    });

    await expect(sourceResponse(service).json()).resolves.toEqual({
      source: {
        manifestPath: "deployment.yaml",
        repository: "owner/repo",
      },
    });
  });

  it("maps synchronous initial storage failure to a safe 503", async () => {
    const service = createService();
    vi.spyOn(service, "start").mockImplementation(() => {
      throw new ScanExecutionError("STORAGE_WRITE_FAILED");
    });

    const response = await startScanResponse(
      post('{"ref":"main"}'),
      service,
      vi.fn(),
    );
    expect(response.status).toBe(503);
    await expect(response.json()).resolves.toEqual({
      error: {
        code: "STORAGE_WRITE_FAILED",
        message: "Scan progress could not be saved.",
      },
    });
  });
});

