name: trusted-delivery

on:
  push:
    branches:
      - "**"

permissions:
  contents: read

jobs:
  verify:
    name: verify
    if: >-
      github.repository == 'RGCsAGupta/driftlens' &&
      github.actor == github.repository_owner
    runs-on:
      - self-hosted
      - Linux
      - X64
      - driftlens-ci
    timeout-minutes: 20
    steps:
      - name: Check out the pushed revision
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          persist-credentials: false

      - name: Set up Node.js
        uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020
        with:
          node-version: 24.15.0

      - name: Verify delivery policy
        run: >-
          node --test
          tests/workflow-policy.test.mjs
          tests/deployment-policy.test.mjs

      - name: Check target script syntax
        run: sh -n ops/deployment/v1/*.sh

      - name: Cache npm downloads
        if: hashFiles('package-lock.json') != ''
        uses: actions/cache@55cc8345863c7cc4c66a329aec7e433d2d1c52a9
        with:
          path: ~/.npm
          key: ${{ runner.os }}-npm-${{ hashFiles('package-lock.json') }}

      - name: Install application dependencies
        if: hashFiles('package-lock.json') != ''
        run: npm ci

      - name: Run application quality gates
        if: hashFiles('package-lock.json') != ''
        run: npm run verify

      - name: Require the application foundation on main
        if: github.ref == 'refs/heads/main' && hashFiles('package-lock.json') == ''
        run: |
          echo "Application foundation missing; main release blocked." >&2
          exit 1

  release:
    name: private-release
    needs:
      - verify
    if: >-
      github.ref == 'refs/heads/main' &&
      github.repository == 'RGCsAGupta/driftlens' &&
      github.actor == github.repository_owner
    runs-on:
      - self-hosted
      - Linux
      - X64
      - driftlens-deploy
    timeout-minutes: 30
    environment:
      name: private-demo
    concurrency:
      group: driftlens-private-deployment
      cancel-in-progress: false
    steps:
      - name: Check out the verified revision
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          persist-credentials: false

      - name: Validate and mask release inputs
        env:
          DEPLOY_HOST: ${{ secrets.DRIFTLENS_DEPLOY_HOST }}
          DEPLOY_KNOWN_HOSTS: ${{ secrets.DRIFTLENS_DEPLOY_KNOWN_HOSTS }}
          DEPLOY_SSH_KEY: ${{ secrets.DRIFTLENS_DEPLOY_SSH_KEY }}
          DEPLOY_USER: ${{ secrets.DRIFTLENS_DEPLOY_USER }}
          REGISTRY: ${{ secrets.DRIFTLENS_REGISTRY }}
          REGISTRY_PASSWORD: ${{ secrets.DRIFTLENS_REGISTRY_PASSWORD }}
          REGISTRY_USERNAME: ${{ secrets.DRIFTLENS_REGISTRY_USERNAME }}
        run: |
          set -eu
          for value in \
            "$DEPLOY_HOST" \
            "$DEPLOY_KNOWN_HOSTS" \
            "$DEPLOY_SSH_KEY" \
            "$DEPLOY_USER" \
            "$REGISTRY" \
            "$REGISTRY_PASSWORD" \
            "$REGISTRY_USERNAME"
          do
            test -n "$value"
          done
          printf '%s' "$GITHUB_SHA" | grep -Eq '^[0-9a-f]{40}$'
          printf '%s' "$DEPLOY_USER" | grep -Eq '^[a-z_][a-z0-9_-]*$'
          printf '%s' "$DEPLOY_HOST" | grep -Eq '^([A-Za-z0-9.-]+|\[[0-9A-Fa-f:]+\])$'
          printf '%s' "$REGISTRY" |
            grep -Eq '^([A-Za-z0-9.-]+|\[[0-9A-Fa-f:]+\])(:[0-9]{1,5})?$'
          printf '%s' "$REGISTRY_USERNAME" |
            grep -Eq '^[A-Za-z0-9._@-]+$'
          if printf '%s' "$REGISTRY_PASSWORD" |
            LC_ALL=C grep -q '[[:cntrl:]]'
          then
            echo "Registry password contains unsupported control characters." >&2
            exit 1
          fi
          test "${REGISTRY#http://}" = "$REGISTRY"
          test "${REGISTRY#https://}" = "$REGISTRY"
          for value in \
            "$DEPLOY_HOST" \
            "$DEPLOY_USER" \
            "$REGISTRY" \
            "$REGISTRY_USERNAME"
          do
            echo "::add-mask::$value"
          done

      - name: Build and publish immutable image
        id: publish
        env:
          DOCKER_CONFIG: ${{ runner.temp }}/driftlens-docker-config
          REGISTRY: ${{ secrets.DRIFTLENS_REGISTRY }}
          REGISTRY_PASSWORD: ${{ secrets.DRIFTLENS_REGISTRY_PASSWORD }}
          REGISTRY_USERNAME: ${{ secrets.DRIFTLENS_REGISTRY_USERNAME }}
        run: |
          set -eu
          install -m 0700 -d "$DOCKER_CONFIG"
          image_tag="${REGISTRY%/}/driftlens:${GITHUB_SHA}"
          echo "::add-mask::$image_tag"
          printf '%s' "$REGISTRY_PASSWORD" |
            docker login "$REGISTRY" --username "$REGISTRY_USERNAME" --password-stdin
          docker build \
            --build-arg "DRIFTLENS_BUILD_SHA=$GITHUB_SHA" \
            --tag "$image_tag" \
            .
          docker push "$image_tag"
          repository="${REGISTRY%/}/driftlens"
          image_digest=""
          while IFS= read -r candidate
          do
            if test "${candidate%%@*}" = "$repository"; then
              test -z "$image_digest"
              image_digest="$candidate"
            fi
          done <<EOF
          $(docker image inspect "$image_tag" --format '{{range .RepoDigests}}{{println .}}{{end}}')
          EOF
          printf '%s' "$image_digest" | grep -Eq '@sha256:[0-9a-f]{64}$'
          echo "::add-mask::$image_digest"
          printf 'image_tag=%s\n' "$image_tag" >> "$GITHUB_OUTPUT"
          printf 'image_digest=%s\n' "$image_digest" >> "$GITHUB_OUTPUT"

      - name: Configure pinned SSH trust
        env:
          DEPLOY_HOST: ${{ secrets.DRIFTLENS_DEPLOY_HOST }}
          DEPLOY_KNOWN_HOSTS: ${{ secrets.DRIFTLENS_DEPLOY_KNOWN_HOSTS }}
          DEPLOY_SSH_KEY: ${{ secrets.DRIFTLENS_DEPLOY_SSH_KEY }}
          DEPLOY_USER: ${{ secrets.DRIFTLENS_DEPLOY_USER }}
        run: |
          set -eu
          install -m 0700 -d "$RUNNER_TEMP/driftlens-ssh"
          printf '%s\n' "$DEPLOY_SSH_KEY" > "$RUNNER_TEMP/driftlens-ssh/key"
          printf '%s\n' "$DEPLOY_KNOWN_HOSTS" > "$RUNNER_TEMP/driftlens-ssh/known_hosts"
          chmod 0600 \
            "$RUNNER_TEMP/driftlens-ssh/key" \
            "$RUNNER_TEMP/driftlens-ssh/known_hosts"
          ssh-keygen -l -f "$RUNNER_TEMP/driftlens-ssh/key" >/dev/null
          ssh-keygen -F "$DEPLOY_HOST" -f "$RUNNER_TEMP/driftlens-ssh/known_hosts" >/dev/null
          {
            echo "Host driftlens-target"
            printf '  HostName %s\n' "$DEPLOY_HOST"
            printf '  User %s\n' "$DEPLOY_USER"
            echo "  BatchMode yes"
            echo "  ConnectTimeout 10"
            echo "  IdentitiesOnly yes"
            echo "  LogLevel ERROR"
            echo "  StrictHostKeyChecking yes"
            echo "  IdentityFile $RUNNER_TEMP/driftlens-ssh/key"
            echo "  UserKnownHostsFile $RUNNER_TEMP/driftlens-ssh/known_hosts"
          } > "$RUNNER_TEMP/driftlens-ssh/config"
          chmod 0600 "$RUNNER_TEMP/driftlens-ssh/config"

      - name: Deploy exact digest with transient target registry authentication
        env:
          IMAGE_DIGEST: ${{ steps.publish.outputs.image_digest }}
          REGISTRY_PASSWORD: ${{ secrets.DRIFTLENS_REGISTRY_PASSWORD }}
          REGISTRY_USERNAME: ${{ secrets.DRIFTLENS_REGISTRY_USERNAME }}
        run: |
          set -eu
          {
            printf '%s\n' "$REGISTRY_USERNAME"
            printf '%s\n' "$REGISTRY_PASSWORD"
          } |
            ssh -F "$RUNNER_TEMP/driftlens-ssh/config" driftlens-target \
              sudo --non-interactive /usr/local/sbin/driftlens-release \
                "$IMAGE_DIGEST" \
                "$GITHUB_SHA"

      - name: Verify private health, readiness, and version
        run: |
          set -eu
          ssh -F "$RUNNER_TEMP/driftlens-ssh/config" driftlens-target \
            sudo --non-interactive /usr/local/sbin/driftlens-smoke \
              "$GITHUB_SHA"

      - name: Remove transient release material
        if: always()
        env:
          DOCKER_CONFIG: ${{ runner.temp }}/driftlens-docker-config
          IMAGE_DIGEST: ${{ steps.publish.outputs.image_digest }}
          IMAGE_TAG: ${{ steps.publish.outputs.image_tag }}
          REGISTRY: ${{ secrets.DRIFTLENS_REGISTRY }}
        run: |
          docker logout "$REGISTRY" >/dev/null 2>&1 || true
          docker image rm "$IMAGE_DIGEST" "$IMAGE_TAG" >/dev/null 2>&1 || true
          rm -f "$DOCKER_CONFIG/config.json"
          rmdir "$DOCKER_CONFIG" 2>/dev/null || true
          rm -f \
            "$RUNNER_TEMP/driftlens-ssh/config" \
            "$RUNNER_TEMP/driftlens-ssh/key" \
            "$RUNNER_TEMP/driftlens-ssh/known_hosts"
          rmdir "$RUNNER_TEMP/driftlens-ssh" 2>/dev/null || true
import assert from "node:assert/strict";

const FULL_SHA = "[0-9a-f]{40}";
const APPROVED_ACTIONS = new Map([
  ["actions/cache", "55cc8345863c7cc4c66a329aec7e433d2d1c52a9"],
  ["actions/checkout", "3d3c42e5aac5ba805825da76410c181273ba90b1"],
  ["actions/setup-node", "820762786026740c76f36085b0efc47a31fe5020"],
]);
const FORBIDDEN_EVENTS = [
  "pull_request",
  "pull_request_target",
  "issue_comment",
  "workflow_dispatch",
  "workflow_call",
  "schedule",
];

function jobSlice(workflow, jobName, nextJobName) {
  const start = workflow.indexOf(`  ${jobName}:`);
  assert.notEqual(start, -1, `missing ${jobName} job`);

  if (!nextJobName) {
    return workflow.slice(start);
  }

  const end = workflow.indexOf(`  ${nextJobName}:`, start + 1);
  assert.notEqual(end, -1, `missing ${nextJobName} job`);
  return workflow.slice(start, end);
}

export function validateWorkflowPolicy(workflow) {
  assert.match(workflow, /^on:\n {2}push:\n {4}branches:\n {6}- "\*\*"$/m);
  for (const event of FORBIDDEN_EVENTS) {
    assert.doesNotMatch(workflow, new RegExp(`^  ${event}:`, "m"));
  }

  assert.match(workflow, /^permissions:\n {2}contents: read$/m);

  const actionReferences = [...workflow.matchAll(/^\s+uses:\s+([^\s#]+)$/gm)];
  assert.ok(actionReferences.length > 0, "workflow must use pinned actions");
  for (const [, reference] of actionReferences) {
    assert.match(reference, new RegExp(`^[^@]+@${FULL_SHA}$`));
    const [action, revision] = reference.split("@");
    assert.equal(
      APPROVED_ACTIONS.get(action),
      revision,
      `unapproved action reference: ${action}`,
    );
  }

  const verify = jobSlice(workflow, "verify", "release");
  assert.match(verify, /name: verify/);
  assert.match(verify, /github\.repository == 'RGCsAGupta\/driftlens'/);
  assert.match(verify, /github\.actor == github\.repository_owner/);
  assert.match(verify, /- driftlens-ci/);
  assert.match(verify, /timeout-minutes: 20/);
  assert.match(verify, /node --test/);
  assert.match(verify, /tests\/workflow-policy\.test\.mjs/);
  assert.match(verify, /tests\/deployment-policy\.test\.mjs/);
  assert.match(verify, /sh -n ops\/deployment\/v1\/\*\.sh/);
  assert.match(verify, /npm ci/);
  assert.match(verify, /npm run verify/);
  assert.doesNotMatch(verify, /REGISTRY_PASSWORD|DEPLOY_SSH_KEY/);

  const release = jobSlice(workflow, "release");
  assert.match(release, /github\.ref == 'refs\/heads\/main'/);
  assert.match(release, /- driftlens-deploy/);
  assert.match(release, /timeout-minutes: 30/);
  assert.match(release, /name: private-demo/);
  assert.match(release, /group: driftlens-private-deployment/);
  assert.match(release, /cancel-in-progress: false/);
  assert.match(release, /driftlens:\$\{GITHUB_SHA\}/);
  assert.match(release, /DRIFTLENS_BUILD_SHA=\$GITHUB_SHA/);
  assert.match(release, /image_digest/);
  assert.match(release, /repository="\$\{REGISTRY%\/\}\/driftlens"/);
  assert.match(release, /\$\{candidate%%@\*\}" = "\$repository"/);
  assert.doesNotMatch(release, /(^|[^a-z])latest([^a-z]|$)/i);
  assert.match(release, /BatchMode yes/);
  assert.match(release, /StrictHostKeyChecking yes/);
  assert.match(release, /UserKnownHostsFile /);
  assert.match(release, /echo "::add-mask::\$value"/);
  assert.match(
    release,
    /DOCKER_CONFIG: \$\{\{ runner\.temp \}\}\/driftlens-docker-config/,
  );
  assert.match(release, /install -m 0700 -d "\$DOCKER_CONFIG"/);
  assert.match(release, /rm -f "\$DOCKER_CONFIG\/config\.json"/);
  assert.match(
    release,
    /printf '%s\\n' "\$REGISTRY_USERNAME"[\s\S]*printf '%s\\n' "\$REGISTRY_PASSWORD"[\s\S]*ssh -F "\$RUNNER_TEMP\/driftlens-ssh\/config"/,
  );
  assert.match(
    release,
    /sudo --non-interactive \/usr\/local\/sbin\/driftlens-release/,
  );
  assert.match(
    release,
    /sudo --non-interactive \/usr\/local\/sbin\/driftlens-smoke\s+\\?\n\s+"\$GITHUB_SHA"/,
  );
  assert.match(release, /if: always\(\)/);
}
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import { validateWorkflowPolicy } from "../scripts/workflow-policy.mjs";

const workflowPath = new URL(
  "../.github/workflows/trusted-delivery.yml",
  import.meta.url,
);

test("trusted workflow satisfies the canonical push and release contract", async () => {
  const workflow = await readFile(workflowPath, "utf8");

  assert.doesNotThrow(() => validateWorkflowPolicy(workflow));
});

test("running deployment remains non-cancellable when a newer revision arrives", async () => {
  const workflow = await readFile(workflowPath, "utf8");

  assert.match(
    workflow,
    /group: driftlens-private-deployment\n {6}cancel-in-progress: false/,
