:root { color-scheme: dark; --bg: #07100e; --panel: #10211d; --border: #284b41; --text: #edf8f4; --muted: #9cb7ae; --accent: #5de0b0; --danger: #ffb4a8; }
* { box-sizing: border-box; }
body { margin: 0; background: radial-gradient(circle at 20% 0%, #173d32, transparent 36%), var(--bg); color: var(--text); font-family: Inter, ui-sans-serif, system-ui, sans-serif; }
button, input { font: inherit; }
button:focus-visible, input:focus-visible { outline: 3px solid #fff; outline-offset: 3px; }
main { min-height: 100vh; padding: 32px 20px; }
.console-layout { margin: 0 auto; max-width: 1180px; }
.console-header { display: grid; gap: 14px; grid-template-columns: 1fr auto; margin-bottom: 24px; }
.console-header h1 { font-size: clamp(3rem, 8vw, 5.5rem); letter-spacing: -.07em; line-height: .9; margin: 8px 0 0; }
.console-header > p { color: var(--muted); max-width: 520px; }
.eyebrow, .section-kicker { color: var(--accent); font-size: .75rem; font-weight: 800; letter-spacing: .12em; margin: 0; text-transform: uppercase; }
.source-line { align-items: flex-end; display: flex; flex-direction: column; gap: 4px; grid-column: 2; }
.source-line span { font-family: ui-monospace, monospace; }
.scan-control, .history-panel, .result-panel { background: rgba(16,33,29,.94); border: 1px solid var(--border); border-radius: 18px; }
.scan-control { margin-bottom: 18px; padding: 22px; }
.scan-control h2, .panel-heading h2 { margin-top: 0; }
.scan-control label { display: block; font-weight: 700; margin-bottom: 8px; }
.control-row { display: flex; gap: 10px; }
input { background: #07100e; border: 1px solid #52766b; border-radius: 10px; color: var(--text); flex: 1; min-width: 0; padding: 12px 14px; }
button { background: var(--accent); border: 0; border-radius: 10px; color: #042119; cursor: pointer; font-weight: 800; padding: 12px 18px; }
button:disabled { cursor: not-allowed; opacity: .6; }
.console-message, .error-panel { background: rgba(255,180,168,.1); border-left: 3px solid var(--danger); color: var(--danger); margin-top: 14px; overflow-wrap: anywhere; padding: 12px 14px; }
.workspace-grid { display: grid; gap: 18px; grid-template-columns: minmax(240px, .75fr) minmax(0, 2fr); }
.history-panel, .result-panel { min-height: 390px; padding: 20px; }
.panel-heading { align-items: baseline; display: flex; justify-content: space-between; }
.panel-heading span, .history-panel p { color: var(--muted); font-size: .85rem; }
.history-panel ul { display: grid; gap: 8px; list-style: none; margin: 0; padding: 0; }
.history-panel button { align-items: flex-start; background: #0a1714; border: 1px solid transparent; color: var(--text); display: flex; flex-direction: column; gap: 4px; text-align: left; width: 100%; }
.history-panel button[aria-current="true"] { border-color: var(--accent); }
.history-panel button span { color: var(--muted); font-size: .78rem; }
.detail-heading { align-items: flex-start; display: flex; gap: 20px; justify-content: space-between; }
.detail-heading h2 { margin: 5px 0 0; overflow-wrap: anywhere; }
.status-badge { border: 1px solid currentColor; border-radius: 999px; font-size: .78rem; font-weight: 800; padding: 7px 10px; text-transform: uppercase; }
.status-failed { color: var(--danger); }
.scan-meta { display: grid; gap: 12px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.scan-meta div { background: #0a1714; border-radius: 10px; padding: 12px; }
.scan-meta dt { color: var(--muted); font-size: .75rem; margin-bottom: 5px; text-transform: uppercase; }
.scan-meta dd { margin: 0; overflow-wrap: anywhere; }
.code-value { font-family: ui-monospace, monospace; font-size: .78rem; }
.outcome-copy { font-size: 1.1rem; font-weight: 700; }
.table-wrap { overflow-x: auto; }
table { border-collapse: collapse; margin-top: 18px; width: 100%; }
caption { font-weight: 800; padding-bottom: 10px; text-align: left; }
th, td { border-bottom: 1px solid var(--border); padding: 12px 8px; text-align: left; overflow-wrap: anywhere; }
.empty-result { color: var(--muted); }
@media (max-width: 760px) { main { padding: 18px 12px; } .console-header, .workspace-grid { grid-template-columns: 1fr; } .source-line { align-items: flex-start; grid-column: 1; } .control-row { flex-direction: column; } .scan-meta { grid-template-columns: 1fr; } }

