export DRIFTLENS_MANIFEST_PATH=path/to/deployment.yaml
export DRIFTLENS_KUBECONFIG_PATH=/absolute/path/to/read-only.kubeconfig
# Optional: export DRIFTLENS_KUBECONTEXT=explicit-context
